#include <vector>
#include <sstream>
#include <algorithm>

using namespace std;

string inputString;
size_t currentLine = 0;

string readLine() {
    size_t start = currentLine;
    size_t end = inputString.find('\n', currentLine);
    if (end == string::npos) {
        end = inputString.size();
    }
    currentLine = end + 1;
    string line = inputString.substr(start, end - start);
    // Trim leading and trailing whitespace
    size_t first = line.find_first_not_of(" \t\r\n");
    if (first == string::npos) return "";
    size_t last = line.find_last_not_of(" \t\r\n");
    return line.substr(first, last - first + 1);
}

void main() {
    string line = readLine();
    istringstream iss(line);
    int n, t;
    iss >> n >> t;

    string str = readLine();

    for (int i = 0; i < t; i++) {
        int j = 0;
        while (j < n - 1) {
            if (str[j] == 'B' && str[j + 1] == 'G') {
                str[j] = 'G';
                str[j + 1] = 'B';
                j++;
            }
            j++;
        }
    }

    cout << str << endl;
}

int main() {
    // Read all input from stdin
    string line;
    while (getline(cin, line)) {
        inputString += line;
        inputString += '\n';
    }

    // Trim the entire input string and split by newlines
    size_t first = inputString.find_first_not_of(" \t\r\n");
    if (first != string::npos) {
        size_t last = inputString.find_last_not_of(" \t\r\n");
        inputString = inputString.substr(first, last - first + 1);
    }

    // Split into lines and trim each line
    vector<string> lines;
    istringstream iss(inputString);
    string line;
    while (getline(iss, line)) {
        size_t first = line.find_first_not_of(" \t\r\n");
        if (first == string::npos) {
            lines.push_back("");
        } else {
            size_t last = line.find_last_not_of(" \t\r\n");
            lines.push_back(line.substr(first, last - first + 1));
        }
    }

    // Reconstruct inputString from trimmed lines
    inputString.clear();
    for (size_t i = 0; i < lines.size(); i++) {
        if (i > 0) inputString += '\n';
        inputString += lines[i];
    }

    currentLine = 0;
    main();

    return 0;
}
