int main() {
    string inputString;
    vector<string> lines;

    // Read all input
    string line;
    while (getline(cin, line)) {
        lines.push_back(line);
    }

    // Trim and split lines
    vector<string> trimmedLines;
    for (const string& l : lines) {
        // Trim leading and trailing whitespace
        size_t start = l.find_first_not_of(" \t\n\r");
        size_t end = l.find_last_not_of(" \t\n\r");
        if (start != string::npos && end != string::npos) {
            trimmedLines.push_back(l.substr(start, end - start + 1));
        } else {
            trimmedLines.push_back("");
        }
    }

    size_t currentLine = 0;
    auto readLine = [&]() -> string {
        if (currentLine < trimmedLines.size()) {
            return trimmedLines[currentLine++];
        }
        return "";
    };

    // Read n and t
    string firstLine = readLine();
    istringstream iss(firstLine);
    int n, t;
    iss >> n >> t;

    // Read the string
    string str = readLine();

    // Process t iterations
    for (int i = 0; i < t; i++) {
        int j = 0;
